#include "d256_provider.hpp"
#include <audio_sdk/session_v0.h>
#include <array>
#include <fstream>
#include <iostream>
#include <iterator>
#include <string>
#include <vector>

static std::string read(const char*p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("fixture file missing");return {std::istreambuf_iterator<char>(f),{}};}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage: d256_regression descriptor.json config-schema.json");std::string descriptor=read(argv[1]),config_schema=read(argv[2]);(void)config_schema;as_registry_v0*registry=nullptr;as_error_v0 error;as_error_v0_init(&error);if(as_registry_create_v0(&registry,&error)!=AS_OK)throw std::runtime_error("registry create failed");const auto*table=audio_bench_d256_provider();auto status=as_register_provider_v0(registry,table,descriptor.data(),uint32_t(descriptor.size()),&error);if(status!=AS_OK)throw std::runtime_error(std::string("fixture provider registration failed: ")+error.message);constexpr char id[]="bench.delay256.fixture.v0";uint32_t n=0;std::vector<char>config(AS_MAX_CONTROL_BYTES+1);status=as_effective_config_create_v0(registry,id,sizeof(id)-1,AS_MODE_PROCESSING_THREAD,config.data(),uint32_t(config.size()),&n,&error);if(status!=AS_OK||!n||n>config.size())throw std::runtime_error("effective config generation failed");as_create_config_v0 c;as_create_config_v0_init(&c);c.execution_mode=AS_MODE_PROCESSING_THREAD;c.epoch=1;c.first_input_sample=0;c.config_json=config.data();c.config_json_length=n-1;as_session_v0*session=nullptr;status=as_session_create_v0(registry,id,sizeof(id)-1,&c,&session,&error);if(status!=AS_OK)throw std::runtime_error(std::string("session creation failed: ")+error.message);std::array<float,160>input{},output{};as_output_v0 out;as_output_v0_init(&out);out.samples=output.data();out.capacity=160;as_result_v0 result;as_result_v0_init(&result);for(int frame=0;frame<2;frame++){input.fill(float(frame+1));as_frame_v0 f;as_frame_v0_init(&f);f.input=input.data();f.input_count=160;f.input_valid_count=160;f.epoch=1;f.first_input_sample=frame*160;status=as_session_process_v0(session,&f,&out,&result);if(status!=AS_OK){std::cout<<"{\"status\":\"blocked\",\"reason\":\"non_frame_aligned_startup_validity\",\"frame\":"<<frame<<",\"sdk_status\":"<<status<<"}\n";as_session_close_v0(&session);as_registry_close_v0(&registry);return 0;}if(frame==1&&(result.source_first_sample!=-96||result.valid_offset!=96||result.valid_count!=64)){std::cout<<"{\"status\":\"blocked\",\"reason\":\"non_frame_aligned_startup_validity\",\"source_first_sample\":"<<result.source_first_sample<<",\"valid_offset\":"<<result.valid_offset<<",\"valid_count\":"<<result.valid_count<<"}\n";as_session_close_v0(&session);as_registry_close_v0(&registry);return 0;}}
std::cout<<"{\"status\":\"passed\",\"reason\":\"non_frame_aligned_startup_validity\",\"source_first_sample\":-96,\"valid_offset\":96,\"valid_count\":64}\n";as_session_close_v0(&session);as_registry_close_v0(&registry);return 0;}catch(const std::exception&e){std::cerr<<"d256 regression setup error: "<<e.what()<<"\n";return 2;}}
